fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(n:&str,v:&Value){let p=format!("{R}/{n}");assert!(!Path::new(&p).exists());fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn rem(v:BigInt,p:&BigInt)->BigInt{let v=v%p;if v.sign()==Sign::Minus{v+p}else{v}}
fn parse(v:&Value)->BigInt{BigInt::parse_bytes(v.as_str().unwrap().as_bytes(),10).unwrap()}
fn array(v:&Value)->[BigInt;6]{core::array::from_fn(|i|parse(&v[i]))}
fn eval(a:&[BigInt;6],g:&BigInt,p:&BigInt)->BigInt{rem((0..6).map(|i|&a[i]*g.pow(i as u32)).sum(),p)}
fn absolute(v:&BigInt)->BigInt{if v.sign()==Sign::Minus{-v}else{v.clone()}}
fn is_power_two(v:&BigInt)->bool{v>&BigInt::from(0)&&(v&(v-1u32))==BigInt::from(0)}
type Q=[u64;3];
fn plus(a:Q,b:Q)->Q{core::array::from_fn(|i|a[i]+b[i])}
fn times(a:Q,b:Q)->Q{let mut out=[0;5];for i in 0..3{for j in 0..3{out[i+j]+=a[i]*b[j];}}assert_eq!(&out[3..],&[0,0]);out[..3].try_into().unwrap()}
fn at(a:Q,n:u64)->u64{a[0]+a[1]*n+a[2]*n*n}
