 let a=read(format!("{R}/analysis.json"));let constants=read(format!("{R}/constants.json"));let ranges=read(format!("{R}/point-bounds.json"));let source=read(format!("{R}/source-context.json"));assert_eq!(a["passed"],true);assert_eq!(source["passed"],true);
 let text=fs::read_to_string(format!("{Z}/crates/zopro-core/src/msm/g2_borrowed.rs")).unwrap();let prefix=text.split_once("    s.tail.clear();").unwrap().0;assert_eq!(prefix.matches("fq2_pack(").count(),2);let rev=text.split_once("    for j in (0..full / LANES).rev()").unwrap().1.split_once("impl<C: CurveConfig<Base = Fq2>> BatchAdd<C>").unwrap().0;assert_eq!(rev.matches("fq2_pack(").count(),5);assert_eq!(rev.matches("fq2_unpack(").count(),2);
 assert_eq!(source["G2_coordinate_vector_imports"],(2+5-1)*2);assert_eq!(source["G2_coordinate_vector_exports"],2*2);assert_eq!(source["G1_both_constructor_branches_import_coordinate_vectors"],4);assert_eq!(source["G1_export_coordinate_vectors"],2);
