 let p=BigInt::parse_bytes(b"21888242871839275222246405745257275088696311157297823662689037894645226208583",10).unwrap();let one=BigInt::from(1u32);let b:BigInt=&one<<52usize;let h:BigInt=&one<<256usize;let h_inv=h.modpow(&(&p-2u32),&p);let b_inv=b.modpow(&(&p-2u32),&p);
 let old_parameters=read(format!("{Z}/docs/benchmarks/2026-10-23-pmns-field-component/experiment/parameters.json"));let selected=old_parameters["candidates"].as_array().unwrap().iter().filter(|v|v["field"]=="Fq"&&v["c"]==0&&v["d"]==2).collect::<Vec<_>>();assert_eq!(selected.len(),6);let original=fs::read_to_string(format!("{Z}/docs/benchmarks/2026-10-23-pmns-field-component/experiment/parameters.json")).unwrap();
