 assert_eq!(ranges["recurrences"].as_array().unwrap().len(),65);for (i,row) in ranges["recurrences"].as_array().unwrap().iter().enumerate(){let n=i as u64;assert_eq!(row["prior_unrenormalized_updates"],n);assert_eq!(row["G2_norm_raw_coefficient"],at(norm,n));assert_eq!(row["G2_numerator_raw_coefficient"],at(numerator,n));assert_eq!(row["G2_finish_raw_coefficient"],at(finish,n));assert_eq!(row["G1_finish_raw_coefficient"],at([4,4,0],n));assert_eq!(row["G2_output_x_bounds"],json!([at(plus(x0,[2,0,0]),n),at(plus(x1,[3,0,0]),n)]));assert_eq!(row["G2_output_y_bound"],n+2);}
 let parent=read("/home/ubuntu/src/zopro-perf-work/pmns-toeplitz6-feasibility176/analysis.json");let parent_rows=parent["surviving_necessary_geometries"].as_array().unwrap();for (i,g) in ranges["necessary_geometry_bounds"].as_array().unwrap().iter().enumerate(){let old=&parent_rows[i];assert_eq!(g["field"],old["field"]);assert_eq!(g["lambda"],old["lambda"]);let w=BigInt::from(old["w"].as_u64().unwrap());let s=BigInt::from(old["ceil_p_sixth_root"].as_u64().unwrap());for(key,c)in[("G1_first_update_certificate_not_excluded",4u32),("G2_first_update_certificate_not_excluded",9),("G2_retained_bucket_second_update_certificate_not_excluded",41)]{let ok=BigInt::from(4*c)*&w*(&b-1u32)*&s<=&b*&b;assert_eq!(g[key],ok);}}
